/// <summary>
/// Extension class of form data source WMSPickingRoute in form WMSPickingRoutesJournal
/// </summary>
[ExtensionOf(formDataSourceStr(WMSPickingRoutesJournal, WMSPickingRoute))]
internal final class METWMSPickingRoutesJournalFormPickingRouteDS_Extension
{
}

Method.Source:
/// <summary>
/// active method on WMSPickingRoute datasource
/// </summary>
/// <returns>
/// int
/// </returns>
int active()
{
    int ret = next active();

    if (element.args().dataset() == tableNum(SalesTable))
    {
        SalesTable  salesTableLoc = element.args().record();
        MetSalesTable   metSalesTable = METSalesTable::findByRefRecId(salesTableLoc.RecId);
        InventLocation  inventLocation = InventLocation::find(salesTableLoc.InventLocationId);
        WMSPickingRoute wMSPickingRoute = this.cursor() as WMSPickingRoute;
        this.formRun().control(this.formRun().controlId(formControlStr(WMSPickingRoutesJournal, METTMSEngineSalesOrderPickingList))).enabled(salesTableLoc.SalesStatus != SalesStatus::Canceled
                                            && !metSalesTable.InternalCrossDockOrder && !inventLocation.METCSDWarehouse
                                            && wMSPickingRoute.expeditionStatus == WMSExpeditionStatus::Activated
                                            && salesTableLoc.METOrderExtractStatus == METOrderExtractStatus::Extracted);
    }
    return ret;
}
